public class DateUtils_isSameLocalTime_TriageGen2Test {





    @Test
    public void testIsSameLocalTime_IdenticalCalendars_ReturnsTrue() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        // Ensure they are exactly the same
        cal2.setTimeInMillis(cal1.getTimeInMillis());

        Assert.assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }
















